import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"HA 2026.11 compatibility review","description":"Confirmed checks, local tests and remaining findings for UGSo extensions on Home Assistant 2026.11.","frontmatter":{"title":"HA 2026.11 compatibility review","description":"Confirmed checks, local tests and remaining findings for UGSo extensions on Home Assistant 2026.11."},"headers":[],"relativePath":"en/collection/ha-2026-11-compatibility.md","filePath":"en/collection/ha-2026-11-compatibility.md","lastUpdated":1794652120000}'),r={name:"en/collection/ha-2026-11-compatibility.md"};function s(i,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="ha-2026-11-compatibility-review" tabindex="-1">HA 2026.11 compatibility review <a class="header-anchor" href="#ha-2026-11-compatibility-review" aria-label="Permalink to &quot;HA 2026.11 compatibility review&quot;">​</a></h1><p><strong>As of 2026-11-05 · Core 2026.11.0 · Frontend 20261028.4 · Test system .177 (port 80).</strong></p><p>This overview distinguishes live checks, user confirmations and local tests. It does not certify every feature or hardware variant. The initial review changed no software versions; the subsequent sidebar correction is documented separately below.</p><h2 id="atlas-and-plugins" tabindex="-1">ATLAS and plugins <a class="header-anchor" href="#atlas-and-plugins" aria-label="Permalink to &quot;ATLAS and plugins&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Package</th><th>Result and scope</th></tr></thead><tbody><tr><td>ATLAS App <strong>0.1.334</strong>, Card Editor <strong>0.2.0-alpha.115</strong></td><td>Live: Ingress, hub with six active plugins, editor, HA connection with 35 live entities and existing project list loaded. All 431 HA-package tests, 74 app/frontend tests and TypeScript checks across eleven workspace packages passed.</td></tr><tr><td>File Studio <strong>0.1.52</strong></td><td>Live: file tree, editor interface and approved paths load. Four package tests and catalog validation passed. Existing files were not edited.</td></tr><tr><td>Automation Exporter / Editor <strong>0.1.28</strong></td><td>Live: system automation file read after its own backup; no existing automations present. Nine local tests passed. No writes to HA system files.</td></tr><tr><td>Terminal <strong>0.1.10</strong></td><td>Interface checked live. <strong>The user confirmed on 2026-11-05: ATLAS Terminal works.</strong> This supplements the initial interface-only check; it does not separately validate every SSH target or Oh My Posh theme.</td></tr><tr><td>Icon Library <strong>0.1.9</strong></td><td>Live: 7,447 MDI icons (7.4.47) load and search responds. Ten tests and package validation passed.</td></tr><tr><td>Icon Studio <strong>0.1.17</strong></td><td>Live: collection, SVG preview and drawing interface load. Fifteen tests and package validation passed; existing collection unchanged.</td></tr></tbody></table></div><p>The ATLAS app also passed read-only validation of 523 package files. The isolated Python contract test for the HA integration could not run locally because Home Assistant was not importable; Docker was not running. A complete new project write/restore/HACS round trip was outside this review.</p><h2 id="other-ha-extensions" tabindex="-1">Other HA extensions <a class="header-anchor" href="#other-ha-extensions" aria-label="Permalink to &quot;Other HA extensions&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Package</th><th>Result and limitation</th></tr></thead><tbody><tr><td><a href="/en/collection/dashboard-layout-card-v2/">Dashboard Layout Card V2 <strong>0.1.181</strong></a></td><td>Separate live test passed: add/edit cards in the second section, floating Add button, header/footer and full reload.</td></tr><tr><td><a href="/en/projects/automation-status-card/">Automation Status Card <strong>0.1.3</strong></a></td><td>Live checks passed: rendering, on/off with state confirmation, running execution, trace request, normal completion, checkboxes, select/deselect all and reload. Bubble/Mushroom single-automation examples rendered. Twenty-one local tests passed. Failures and runtime warnings were not deliberately triggered again on 2026.11.</td></tr><tr><td><a href="/en/projects/sidebar-manager/">Sidebar Manager <strong>0.1.9</strong></a></td><td>Updated on .177 from 0.1.7 to <strong>0.1.9</strong>. Live checks passed: entry/group text and icon colors in the native edit dialog, opacity, Cancel, Save, theme reset and a full reload. All 72 local tests passed. Disposable test objects removed; exported layout matches the original backup.</td></tr><tr><td><a href="/en/projects/sidebar-colors/">Sidebar Colors <strong>0.1.1</strong></a></td><td><strong>0.1.1</strong> fixes the same row selector. All 27 local tests passed, including DOM regressions for legacy/new HA elements and Save/Cancel. Not additionally installed alongside Manager on .177.</td></tr><tr><td><a href="/en/projects/dashboard-user-manager/">Dashboard User Manager <strong>0.1.11</strong></a></td><td>Live: 19 views and four users loaded; no changes saved. <strong>Open: additional loading warning for the old <code>lovelace</code> dashboard.</strong> Root cause not fully established. Thirty-three Python and nineteen Node app tests passed.</td></tr><tr><td><a href="/en/projects/grafik-visual-studio/">HA Grafik Visual Studio <strong>0.1.296</strong></a></td><td>109 Python and 388 Node tests passed. No dedicated live test on .177, where the app is not installed.</td></tr><tr><td><a href="/en/projects/blocks-for-ha/">Blocks for HA <strong>0.1.66</strong></a></td><td>Ten Python and 172 Node tests passed; seven optional tests skipped. No live test on .177.</td></tr><tr><td><a href="/en/projects/mqtt-client/">MQTT Client <strong>0.1.17</strong></a></td><td>Thirty-six Python tests passed; two tests requiring a separate MQTT broker skipped. No new live test against an external broker.</td></tr><tr><td><a href="/en/projects/callmebot/">CallMeBot Whatsapp <strong>0.1.6</strong></a> / <a href="/en/projects/callmebot-signal/">Signal <strong>0.1.2</strong></a></td><td>17/18 Python tests and three request-ID tests each passed. No messages sent to actual recipients.</td></tr><tr><td>Tabbed Card V2 / Editor <strong>0.1.7</strong>, HA integration <strong>0.1.3</strong></td><td>JavaScript/Python syntax checked; no live qualification of the uninstalled extension.</td></tr><tr><td><a href="/en/projects/fritzbox-to-mqtt/">FRITZ!Box to MQTT <strong>0.1.41</strong></a> / <a href="/en/projects/heizoel-to-mqtt/">Heating Oil to MQTT <strong>0.1.15</strong></a></td><td>Python syntax checked; devices, data source and MQTT Discovery not tested live.</td></tr><tr><td>Materialdesign widget package / <a href="/en/projects/ultimate-timer/">Ultimate Timer Blueprint</a></td><td>Included in the inventory; no new complete live functional test.</td></tr></tbody></table></div><h2 id="known-findings-and-next-checks" tabindex="-1">Known findings and next checks <a class="header-anchor" href="#known-findings-and-next-checks" aria-label="Permalink to &quot;Known findings and next checks&quot;">​</a></h2><p><strong>Fixed in Sidebar Manager 0.1.9 and Sidebar Colors 0.1.1:</strong> color application now supports legacy <code>ha-md-list-item</code> and new <code>ha-list-item-button</code>. Manager live-tested on .177: entry/group text and icon colors, opacity, Cancel, Save, theme reset and a full reload. All 72 Manager and 27 Colors tests pass. Colors was tested separately locally, not loaded alongside Manager on .177. Stored color settings need no migration.</p><p>The User Manager&#39;s <code>lovelace</code> loading warning requires a separate investigation. Failed reads must still never count as empty dashboards. The warning has not yet been conclusively attributed to a 2026.11 regression.</p><p>Uninstalled apps and untested write, restore, device or broker workflows need additional live checks. Third-party projects such as UIX, Calendar Card Pro, Zendure and Frosted Glass were not fully audited here.</p><h2 id="backup-and-cleanup" tabindex="-1">Backup and cleanup <a class="header-anchor" href="#backup-and-cleanup" aria-label="Permalink to &quot;Backup and cleanup&quot;">​</a></h2><p>A fresh full backup was created first. The owned test automation performed only a delay, with no automatic triggers or device actions. The test automation and dashboard were removed; existing settings, projects, plugins and “Test für APP” were preserved. Following explicit approval to delete the oldest backup, exactly three full backups remain; app-update and PC backups were retained.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.home-assistant.io/blog/2026/11/04/release-202611/" target="_blank" rel="noreferrer">Official HA 2026.11 changes</a></li><li><a href="https://contributors.home-assistant.io/blog/2026/10/28/frontend-component-updates-2026.11/" target="_blank" rel="noreferrer">Frontend components in 2026.11</a></li><li><a href="https://contributors.home-assistant.io/blog/2026/10/23/config-entry-methods-return-none/" target="_blank" rel="noreferrer">Config-entry returns: booleans remain supported for custom integrations</a></li><li><a href="https://github.com/home-assistant/frontend/blob/20261028.4/src/components/ha-items-display-editor.ts" target="_blank" rel="noreferrer">Original display editor 20261028.4</a></li></ul>',16)])])}const u=t(r,[["render",s]]);export{g as __pageData,u as default};
